CREATE OR REPLACE FUNCTION public.share_factory_nine_snapshot(actor_id uuid, request_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE org uuid; project uuid; client uuid; req uuid; item jsonb; existing public.technology_next_shared_snapshots%rowtype; result uuid; role_name text;
BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'Server verified sharing required'; END IF;
 IF jsonb_typeof(request_payload) IS DISTINCT FROM 'object' OR octet_length(request_payload::text)>65536
 OR (SELECT count(*) FROM jsonb_object_keys(request_payload))<>6
 OR NOT request_payload ?& ARRAY['organizationId','projectId','clientWorkspaceId','requestId','title','snapshot'] THEN RAISE EXCEPTION 'Invalid sharing request'; END IF;
 IF jsonb_typeof(request_payload->'title') IS DISTINCT FROM 'string'
 OR jsonb_typeof(request_payload->'clientWorkspaceId') NOT IN('string','null') THEN RAISE EXCEPTION 'Invalid sharing request'; END IF;
 org:=(request_payload->>'organizationId')::uuid;project:=(request_payload->>'projectId')::uuid;
 client:=(request_payload->>'clientWorkspaceId')::uuid;req:=(request_payload->>'requestId')::uuid;item:=request_payload->'snapshot';
 IF actor_id IS NULL OR org IS NULL OR project IS NULL OR req IS NULL THEN RAISE EXCEPTION 'Sharing identity required'; END IF;
 PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Organization unavailable'; END IF;
 SELECT m.role INTO role_name FROM public.organization_members m WHERE m.organization_id=org AND m.user_id=actor_id FOR SHARE;
 IF role_name IS NULL OR role_name NOT IN('owner','admin','manager','member') THEN RAISE EXCEPTION 'Sharing role required'; END IF;
 PERFORM 1 FROM public.profiles p WHERE p.id=actor_id AND p.plan='business' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Business plan required'; END IF;
 PERFORM 1 FROM public.profiles p JOIN public.organizations o ON o.owner_user_id=p.id WHERE o.id=org AND p.plan='business' FOR SHARE OF p;
 IF NOT FOUND THEN RAISE EXCEPTION 'Business organization required'; END IF;
 PERFORM 1 FROM public.business_projects WHERE id=project AND organization_id=org AND status='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Project unavailable'; END IF;
 IF client IS NOT NULL THEN
  PERFORM 1 FROM public.client_workspaces WHERE id=client AND organization_id=org AND (project_id IS NULL OR project_id=project) FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Client workspace unavailable'; END IF;
 END IF;
 IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(item))<>4
 OR NOT item ?& ARRAY['calculatorSlug','calculatorVersion','input','output'] OR jsonb_typeof(item->'calculatorVersion') IS DISTINCT FROM 'number'
 OR item->'calculatorVersion' IS DISTINCT FROM '1'::jsonb
 OR jsonb_typeof(item->'calculatorSlug') IS DISTINCT FROM 'string'
 OR item->>'calculatorSlug' NOT IN('square-calculator','cube-calculator','square-root-calculator','length-converter','energy-converter','power-converter','time-converter','force-converter','frequency-converter','percentage-change-calculator','percentage-increase-calculator','percentage-decrease-calculator','ratio-calculator','proportion-calculator','fraction-to-decimal-calculator','average-two-numbers-calculator','area-converter','volume-converter','temperature-converter','speed-converter','angle-converter','data-storage-converter','capacitance-calculator','free-fall-calculator','angular-velocity-calculator','hypotenuse-calculator','triangle-area-calculator','rectangle-area-calculator','rectangle-perimeter-calculator','circle-area-calculator','circle-circumference-calculator','circle-diameter-calculator','pressure-converter','cooking-measurement-converter','density-converter','torque-converter','square-area-calculator','square-perimeter-calculator','parallelogram-area-calculator','trapezoid-area-calculator','sphere-volume-calculator','sphere-surface-area-calculator','cylinder-volume-calculator','rectangular-prism-volume-calculator','fraction-calculator','cube-root-calculator','exponent-calculator','logarithm-calculator','reciprocal-calculator','remainder-calculator','lcm-calculator','gcf-calculator','factor-calculator','rounding-calculator','scientific-notation-calculator','percent-error-calculator','root-finder-calculator','triangle-calculator','right-triangle-calculator','polygon-area-calculator','cone-volume-calculator','surface-area-calculator','volume-calculator','pythagorean-theorem-calculator','degrees-to-radians-calculator','radians-to-degrees-calculator','molarity-calculator','moles-calculator','dilution-calculator')
 OR jsonb_typeof(item->'input') IS DISTINCT FROM 'object' OR jsonb_typeof(item->'output') IS DISTINCT FROM 'object'
 OR NOT (CASE WHEN item->>'calculatorSlug'='root-finder-calculator' THEN ((SELECT count(*) FROM jsonb_object_keys(item->'output'))=5 AND item->'output' ?& ARRAY['root','residual','iterations','bracket','steps'] AND jsonb_typeof(item->'output'->'root')='number' AND CASE WHEN jsonb_typeof(item->'output'->'root')='number' THEN abs((item->'output'->'root'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'residual')='number' AND CASE WHEN jsonb_typeof(item->'output'->'residual')='number' THEN abs((item->'output'->'residual'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'iterations')='number' AND CASE WHEN jsonb_typeof(item->'output'->'iterations')='number' THEN abs((item->'output'->'iterations'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND CASE WHEN jsonb_typeof(item->'output'->'iterations')='number' THEN (item->'output'->'iterations'#>>'{}')::numeric=trunc((item->'output'->'iterations'#>>'{}')::numeric) AND (item->'output'->'iterations'#>>'{}')::numeric BETWEEN 0 AND 101 ELSE false END AND jsonb_typeof(item->'output'->'bracket')='array' AND jsonb_array_length(item->'output'->'bracket')=2 AND NOT EXISTS(SELECT FROM jsonb_array_elements(item->'output'->'bracket') e WHERE jsonb_typeof(e)<>'number' OR NOT CASE WHEN jsonb_typeof(e)='number' THEN abs((e#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END) AND jsonb_typeof(item->'output'->'steps')='array' AND NOT EXISTS(SELECT FROM jsonb_array_elements(item->'output'->'steps') e WHERE jsonb_typeof(e)<>'string')) WHEN item->>'calculatorSlug'='triangle-calculator' THEN ((SELECT count(*) FROM jsonb_object_keys(item->'output'))=6 AND item->'output' ?& ARRAY['area','perimeter','angleA','angleB','angleC','steps'] AND jsonb_typeof(item->'output'->'area')='number' AND CASE WHEN jsonb_typeof(item->'output'->'area')='number' THEN abs((item->'output'->'area'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'perimeter')='number' AND CASE WHEN jsonb_typeof(item->'output'->'perimeter')='number' THEN abs((item->'output'->'perimeter'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'angleA')='number' AND CASE WHEN jsonb_typeof(item->'output'->'angleA')='number' THEN abs((item->'output'->'angleA'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'angleB')='number' AND CASE WHEN jsonb_typeof(item->'output'->'angleB')='number' THEN abs((item->'output'->'angleB'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'angleC')='number' AND CASE WHEN jsonb_typeof(item->'output'->'angleC')='number' THEN abs((item->'output'->'angleC'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'steps')='array' AND NOT EXISTS(SELECT FROM jsonb_array_elements(item->'output'->'steps') e WHERE jsonb_typeof(e)<>'string')) WHEN item->>'calculatorSlug'='right-triangle-calculator' THEN ((SELECT count(*) FROM jsonb_object_keys(item->'output'))=6 AND item->'output' ?& ARRAY['area','perimeter','angleA','angleB','angleC','steps'] AND jsonb_typeof(item->'output'->'area')='number' AND CASE WHEN jsonb_typeof(item->'output'->'area')='number' THEN abs((item->'output'->'area'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'perimeter')='number' AND CASE WHEN jsonb_typeof(item->'output'->'perimeter')='number' THEN abs((item->'output'->'perimeter'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'angleA')='number' AND CASE WHEN jsonb_typeof(item->'output'->'angleA')='number' THEN abs((item->'output'->'angleA'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'angleB')='number' AND CASE WHEN jsonb_typeof(item->'output'->'angleB')='number' THEN abs((item->'output'->'angleB'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'angleC')='number' AND CASE WHEN jsonb_typeof(item->'output'->'angleC')='number' THEN abs((item->'output'->'angleC'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'steps')='array' AND NOT EXISTS(SELECT FROM jsonb_array_elements(item->'output'->'steps') e WHERE jsonb_typeof(e)<>'string')) WHEN item->>'calculatorSlug'='surface-area-calculator' THEN ((SELECT count(*) FROM jsonb_object_keys(item->'output'))=3 AND item->'output' ?& ARRAY['surfaceArea','volume','steps'] AND jsonb_typeof(item->'output'->'surfaceArea')='number' AND CASE WHEN jsonb_typeof(item->'output'->'surfaceArea')='number' THEN abs((item->'output'->'surfaceArea'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'volume')='number' AND CASE WHEN jsonb_typeof(item->'output'->'volume')='number' THEN abs((item->'output'->'volume'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'steps')='array' AND NOT EXISTS(SELECT FROM jsonb_array_elements(item->'output'->'steps') e WHERE jsonb_typeof(e)<>'string')) WHEN item->>'calculatorSlug'='volume-calculator' THEN ((SELECT count(*) FROM jsonb_object_keys(item->'output'))=3 AND item->'output' ?& ARRAY['surfaceArea','volume','steps'] AND jsonb_typeof(item->'output'->'surfaceArea')='number' AND CASE WHEN jsonb_typeof(item->'output'->'surfaceArea')='number' THEN abs((item->'output'->'surfaceArea'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'volume')='number' AND CASE WHEN jsonb_typeof(item->'output'->'volume')='number' THEN abs((item->'output'->'volume'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'steps')='array' AND NOT EXISTS(SELECT FROM jsonb_array_elements(item->'output'->'steps') e WHERE jsonb_typeof(e)<>'string')) WHEN item->>'calculatorSlug'='molarity-calculator' THEN ((SELECT count(*) FROM jsonb_object_keys(item->'output'))=2 AND item->'output' ?& ARRAY['value','steps'] AND jsonb_typeof(item->'output'->'value')='number' AND CASE WHEN jsonb_typeof(item->'output'->'value')='number' THEN abs((item->'output'->'value'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'steps')='array' AND NOT EXISTS(SELECT FROM jsonb_array_elements(item->'output'->'steps') e WHERE jsonb_typeof(e)<>'string')) WHEN item->>'calculatorSlug'='moles-calculator' THEN ((SELECT count(*) FROM jsonb_object_keys(item->'output'))=2 AND item->'output' ?& ARRAY['value','steps'] AND jsonb_typeof(item->'output'->'value')='number' AND CASE WHEN jsonb_typeof(item->'output'->'value')='number' THEN abs((item->'output'->'value'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'steps')='array' AND NOT EXISTS(SELECT FROM jsonb_array_elements(item->'output'->'steps') e WHERE jsonb_typeof(e)<>'string')) WHEN item->>'calculatorSlug'='dilution-calculator' THEN ((SELECT count(*) FROM jsonb_object_keys(item->'output'))=2 AND item->'output' ?& ARRAY['value','steps'] AND jsonb_typeof(item->'output'->'value')='number' AND CASE WHEN jsonb_typeof(item->'output'->'value')='number' THEN abs((item->'output'->'value'#>>'{}')::numeric)<=1.7976931348623157e308 ELSE false END AND jsonb_typeof(item->'output'->'steps')='array' AND NOT EXISTS(SELECT FROM jsonb_array_elements(item->'output'->'steps') e WHERE jsonb_typeof(e)<>'string')) WHEN item->>'calculatorSlug' IN('capacitance-calculator','free-fall-calculator','angular-velocity-calculator') THEN (SELECT count(*) FROM jsonb_object_keys(item->'output'))=2 AND item->'output' ?& ARRAY['value','steps'] AND jsonb_typeof(item->'output'->'value')='number' AND jsonb_typeof(item->'output'->'steps')='array' AND NOT EXISTS(SELECT FROM jsonb_array_elements(item->'output'->'steps') e WHERE jsonb_typeof(e)<>'string') ELSE (SELECT count(*) FROM jsonb_object_keys(item->'output'))=1 AND jsonb_typeof(item->'output'->'result')='number' END)
 OR char_length(request_payload->>'title') NOT BETWEEN 1 AND 240 THEN RAISE EXCEPTION 'Unsupported shared snapshot'; END IF;
 SELECT * INTO existing FROM public.technology_next_shared_snapshots s
 WHERE s.organization_id=org AND s.created_by=actor_id AND s.request_id=req;
 IF FOUND THEN
  IF existing.request_payload IS DISTINCT FROM request_payload THEN RAISE EXCEPTION 'Sharing request conflicts with original snapshot'; END IF;
  RETURN existing.id;
 END IF;
 INSERT INTO public.technology_next_shared_snapshots(organization_id,project_id,client_workspace_id,created_by,request_id,title,calculator_slug,calculator_version,input_data,output_data,request_payload)
 VALUES(org,project,client,actor_id,req,request_payload->>'title',item->>'calculatorSlug',(item->>'calculatorVersion')::integer,item->'input',item->'output',request_payload) RETURNING id INTO result;
 INSERT INTO public.organization_audit_log(organization_id,actor_user_id,action,entity_type,entity_id,metadata)
 VALUES(org,actor_id,'factory-nine.snapshot.shared','factory-nine-shared-snapshot',result::text,jsonb_build_object('calculatorSlug',item->>'calculatorSlug','calculatorVersion',(item->>'calculatorVersion')::integer,'projectId',project,'clientWorkspaceId',client));
 RETURN result;
END $function$
;
COMMIT;
